{"function": "() => {
    // Extract all publications from the page
    const allText = document.body.textContent;

    // Look for patterns with year in parentheses
    const yearPattern = /\((\d{4})\)/g;

    // Find all publication entries by looking at text that contains author names and years
    const lines = allText.split('\n');
    const publications = [];

    // More specific pattern to match publication entries
    const pubPattern = /([^(]+)\((\d{4})\)([^]+?)(?=\n\n|\n\t|\n[A-Z]|$)/g;

    let match;
    while ((match = pubPattern.exec(allText)) !== null) {
        const authors = match[1].trim();
        const year = parseInt(match[2]);
        const rest = match[3].trim();

        publications.push({
            authors,
            year,
            title: rest.split('- PDF')[0].trim(),
            fullEntry: `${authors} (${year}) ${rest}`
        });
    }

    // Alternative approach: find all (year) patterns and get context
    const entries = [];
    const yearMatches = [...allText.matchAll(/\((\d{4})\)/g)];

    yearMatches.forEach((match, index) => {
        const year = parseInt(match[1]);
        const start = Math.max(0, match.index - 300);
        const end = Math.min(allText.length, match.index + 300);
        const context = allText.substring(start, end);

        // Try to extract a clean entry
        const linesAround = context.split('\n');
        const relevantLines = linesAround.filter(line => 
            line.includes('Murano') || line.includes(year.toString()) || 
            line.includes('PDF') || line.includes('Proceedings') || 
            line.includes('Journal') || line.includes('Conference')
        );

        entries.push({
            year,
            context: relevantLines.join(' ').substring(0, 200)
        });
    });

    return {
        totalPublications: publications.length,
        publications: publications.slice(0, 50), // Return first 50
        yearEntries: entries.slice(0, 30),
        allYears: [...new Set(yearMatches.map(m => parseInt(m[1])))].sort((a, b) => a - b)
    };
}"}

