{"function": "() => {
    // Extract all publication entries from Google Scholar
    const publications = [];

    // Get all table rows containing publications
    const rows = document.querySelectorAll('tbody tr');

    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 3) {
            const titleCell = cells[0];
            const citedByCell = cells[1];
            const yearCell = cells[2];

            const titleLink = titleCell.querySelector('a');
            const title = titleLink ? titleLink.textContent.trim() : titleCell.textContent.trim();

            // Get authors and journal info
            const titleText = titleCell.textContent.trim();
            // Try to extract authors and journal
            const parts = titleText.split(/(?=[A-Z]\.)/);

            const citationInfo = titleCell.querySelectorAll('div, span');
            let authors = '';
            let journal = '';

            if (citationInfo.length > 1) {
                authors = citationInfo[0]?.textContent.trim() || '';
                journal = citationInfo[1]?.textContent.trim() || '';
            }

            const citedBy = citedByCell.textContent.trim();
            const year = yearCell.textContent.trim();

            publications.push({
                title,
                authors: authors || 'Not extracted',
                journal: journal || 'Not extracted',
                citedBy,
                year: parseInt(year),
                fullText: titleText.substring(0, 200)
            });
        }
    });

    return {
        totalPublications: publications.length,
        publications: publications
    };
}"}

{"function": "() => {
    const publications = [];

    // Find all list items
