{"function": "() => {
  const results = [];

  // Find all publication entries
  const entries = document.querySelectorAll('li');

  let currentYear = null;
  let currentType = null;

  entries.forEach(entry => {
    const text = entry.textContent.trim();

    // Check if it's a year header
    if (/^\d{4}$/.test(text)) {
      currentYear = text;
    }
    // Check if it's a publication entry (has authors and title)
    else if (text.includes(':') && text.length > 50) {
      // Clean up the text
      const cleanText = text.replace(/\s+/g, ' ').trim();

      // Extract title (text after the last colon before journal info)
      const parts = cleanText.split(':');
      let title = '';
      let authors = '';
      let venue = '';
      let year = currentYear;

      if (parts.length >= 3) {
        // Authors are before first colon
        authors = parts[0].trim();

        // Title is between first and last colon
        title = parts.slice(1, -1).join(':').trim();

        // Last part contains venue and year
        const lastPart = parts[parts.length - 1].trim();

        // Extract venue and year info
        const venueMatch = lastPart.match(/(.*?)\s*\(\d{4}\)/);
        if (venueMatch) {
          venue = venueMatch[1].trim();
        } else {
          venue = lastPart;
        }
      } else if (parts.length === 2) {
        authors = parts[0].trim();
        title = parts[1].trim();
      }

      results.push({
        year: year,
        authors: authors,
        title: title,
        venue: venue,
        fullText: cleanText
      });
    }
  });

  return results;
}"}

