{"function": "() => {
    // Find the main content area
    const mainDiv = document.querySelector('div[ref="e26"]');
    if (!mainDiv) return { error: 'Main content not found' };

    // Get all text content
    const text = mainDiv.textContent;

    // Extract publication entries with years
    const publicationEntries = [];
    const lines = text.split('\n').map(line => line.trim()).filter(line => line.length > 0);

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // Look for patterns like "Keya, Rashika Tasnim, Heldal, Ilona, Patel, Daniel, Murano, Pietro & Wijkmark, Cecilia Hammar (2025)"
        // or "Murano, Pietro (2001)"
        if (line.includes('Murano') && line.includes('(') && line.includes(')')) {
            // Try to extract year
            const yearMatch = line.match(/\((\d{4})\)/);
            if (yearMatch) {
                const year = parseInt(yearMatch[1]);
                // Get the title from next line or current line
                let title = '';
                if (i + 1 < lines.length && lines[i + 1].includes('PDF')) {
                    // Next line likely contains the title
                    title = lines[i + 1].replace(/ - PDF.*$/, '').trim();
                } else {
                    // Try to extract title from current line
                    const parts = line.split(')');
                    if (parts.length > 1) {
                        title = parts[1].replace(/ - PDF.*$/, '').trim();
                    }
                }

                if (title) {
                    publicationEntries.push({
                        raw: line,
                        year: year,
                        title: title,
                        fullEntry: line + (i + 1 < lines.length ? ' ' + lines[i + 1] : '')
                    });
                }
            }
        }
    }

    return {
        totalEntries: publicationEntries.length,
        entries: publicationEntries.sort((a, b) => a.year - b.year)
    };
