    // Get all text nodes that contain years
    const allText = document.body.innerText;
    const yearMatches = allText.match(/\b(19[0-9]{2}|20[0-9]{2})\b/g) || [];

    // Find the earliest year mentioned
    const years = yearMatches.map(y => parseInt(y)).filter(y => y >= 1900 && y <= 2026);
    const earliestYear = years.length > 0 ? Math.min(...years) : null;

    // Find all occurrences of that earliest year with context
    const earliestEntries = [];
    const lines = allText.split('\n');

    for (const line of lines) {
        if (line.includes(earliestYear.toString())) {
            earliestEntries.push(line.trim());
        }
    }

    return {
        earliestYear: earliestYear,
        allYears: [...new Set(years)].sort((a, b) => a - b),
        earliestEntries: earliestEntries.slice(0, 5)
    };
}"}

