    // Pattern for publications
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];

        // Check if line contains Murano and a year
        if (line.includes('Murano') && line.match(/\(\d{4}\)/)) {
            // Extract year
            const yearMatch = line.match(/\((\d{4})\)/);
            if (yearMatch) {
                const year = parseInt(yearMatch[1]);

                // Look for title - could be in this line or next
                let title = '';

                // Check if this line contains a title after the year
                const afterYear = line.split(/\(\d{4}\)/)[1];
                if (afterYear && afterYear.includes('PDF')) {
                    title = afterYear.split('PDF')[0].trim();
                    if (title.startsWith(')')) title = title.substring(1).trim();
                    if (title.endsWith('-')) title = title.slice(0, -1).trim();
                }

                // If no title found, check next line
                if (!title && i + 1 < lines.length) {
                    const nextLine = lines[i + 1];
                    if (nextLine.includes('PDF')) {
                        title = nextLine.split('PDF')[0].trim();
                        if (title.endsWith('-')) title = title.slice(0, -1).trim();
                    }
                }

                // Clean up title
                if (title) {
                    // Remove quotes if present
                    title = title.replace(/^["']|["']$/g, '');

                    publicationEntries.push({
                        year: year,
                        title: title,
                        rawLine: line
                    });
                }
            }
        }
    }

    // Sort by year
    publicationEntries.sort((a, b) => a.year - b.year);

